CREATE TABLE roles (id BIGSERIAL PRIMARY KEY, name VARCHAR(50) UNIQUE NOT NULL, description VARCHAR(255));
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(100) NOT NULL, full_name VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, phone VARCHAR(20), address VARCHAR(255), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE users_roles (user_id BIGINT NOT NULL REFERENCES users(id), role_id BIGINT NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, slug VARCHAR(120) UNIQUE NOT NULL, description TEXT, image_url VARCHAR(500), display_order INTEGER DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE products (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, slug VARCHAR(250) UNIQUE NOT NULL, description TEXT, price NUMERIC(15,2) NOT NULL, original_price NUMERIC(15,2), stock_quantity INTEGER NOT NULL, unit VARCHAR(50), image_url VARCHAR(500), origin VARCHAR(100), brand VARCHAR(100), discount_percent INTEGER, category_slug VARCHAR(100), rating DOUBLE PRECISION, review_count INTEGER, is_organic BOOLEAN NOT NULL DEFAULT TRUE, is_featured BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, category_id BIGINT REFERENCES categories(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, order_code VARCHAR(50) UNIQUE NOT NULL, user_id BIGINT REFERENCES users(id), recipient_name VARCHAR(100) NOT NULL, recipient_phone VARCHAR(20) NOT NULL, shipping_address VARCHAR(255) NOT NULL, note VARCHAR(500), total_amount NUMERIC(15,2) NOT NULL, payment_method VARCHAR(50) NOT NULL DEFAULT 'COD', is_paid BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), product_id BIGINT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, unit_price NUMERIC(15,2) NOT NULL, total_price NUMERIC(15,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
